from __future__ import annotations
import hashlib, itertools, json
from datetime import datetime, timedelta
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'outputs'/'targeted_24h_amihud'
OUT.mkdir(parents=True,exist_ok=True)

def sha(p:Path)->str:
 h=hashlib.sha256(); h.update(p.read_bytes()); return h.hexdigest()
def dump(name,obj):
 (OUT/name).write_text(json.dumps(obj,indent=2,sort_keys=True,allow_nan=False)+'\n')

def models():
 out={}
 # Exactly 20 bounded configurations in each classical family. The lists are
 # fixed before any comparison and shared between SPOT_ONLY and SPOT_PLUS_DERIVATIVES.
 out['ElasticNet']=[{'alpha':a,'l1_ratio':l,'scaler':s,'max_iter':10000,'tol':1e-4} for a in [1e-4,1e-3,1e-2,.1,1.] for l in [.05,.5] for s in ['standard','robust']]
 out['RBF_SVR']=[{'C':c,'epsilon':e,'gamma':'scale','scaler':s} for c in [.1,1,10,50,100] for e in [.01,.1] for s in ['standard','robust']]
 out['ExtraTrees']=[{'n_estimators':300,'min_samples_leaf':leaf,'max_features':feat,'max_depth':None,'n_jobs':1} for feat in ['sqrt',.3,.6,1.] for leaf in [1,2,5,10,20]]
 out['HistGradientBoosting']=[{'max_iter':150,'max_leaf_nodes':leaf,'learning_rate':lr,'l2_regularization':l2} for leaf in [7,15,31,63,127] for lr in [.03,.1] for l2 in [0.,1.]]
 out['XGBoost']=[{'n_estimators':250,'max_depth':depth,'learning_rate':lr,'subsample':sub,'colsample_bytree':.8,'reg_lambda':1.,'objective':'reg:squarederror','tree_method':'hist','n_jobs':1} for depth in [2,3,4,5,6] for lr in [.03,.1] for sub in [.7,1.]]
 out['LightGBM']=[{'n_estimators':250,'num_leaves':leaves,'learning_rate':lr,'min_child_samples':child,'verbosity':-1,'n_jobs':1} for leaves in [7,15,31,63,127] for lr in [.03,.1] for child in [20,50]]
 out['CatBoost']=[{'iterations':250,'depth':depth,'learning_rate':lr,'l2_leaf_reg':l2,'loss_function':'RMSE','verbose':False,'thread_count':1,'allow_writing_files':False} for depth in [4,6,8,10,12] for lr in [.03,.1] for l2 in [3.,10.]]
 out['MLP']=[{'hidden_layer_sizes':[h],'alpha':a,'scaler':s,'max_iter':300,'early_stopping':False,'tol':1e-4} for h in [16,32,64,96,128] for a in [.0001,.01] for s in ['standard','robust']]
 out['GRU']=[{'hidden_size':h,'learning_rate':lr,'weight_decay':wd,'epochs':50,'batch_size':128,'scaler':'standard'} for h in [8,16,32,48,64] for lr in [.001,.0003] for wd in [0.,.001]]
 assert all(len(v)==20 for v in out.values())
 return out

base_spot=['spot_return','spot_realized_volatility','spot_downside_semivariance','spot_amihud','spot_taker_imbalance','spot_quote_volume_growth']
base_der=['funding_rate_state','oi_log_change','futures_taker_imbalance','basis_mean']
features={
 'source_panel':'data/processed/phase7/market_liquidity_panel_4h.csv.gz',
 'assets':['BTC','ETH'],
 'target':'future_amihud_24h_mean',
 'target_definition':'arithmetic mean of spot_amihud at t+1,...,t+6; all six future intervals required',
 'feature_timing':'six current/past 4-hour intervals t-5..t; interval-t values are available only at its end; target starts at t+1',
 'complete_case':'same asset-date rows for all information sets; all required S0 and S1 fields finite and target finite; no imputation',
 'history_intervals':6,
 'spot_only':{'base_variables':base_spot,'lag_order':'t-5 through t inclusive','calendar_controls':['utc_slot_1..utc_slot_5 (utc_slot_0 reference)','weekday_1..weekday_6 (weekday_0 reference)','funding_schedule_window']},
 'spot_plus_derivatives':{'adds_base_variables':base_der,'lag_order':'t-5 through t inclusive','static_derivative_features':['funding_change','basis_change','oi_shock_30d_robust','flow_shock_30d_robust','funding_x_oi_shock','oi_shock_x_flow_shock','funding_x_basis','flow_x_basis']},
 'derived_definitions':{
  'funding_change':'funding_rate_state[t]-funding_rate_state[t-1]',
  'basis_change':'basis_mean[t]-basis_mean[t-1]',
  'oi_shock_30d_robust':'(oi_log_change[t]-median(oi_log_change[t-180:t-1]))/(1.4826*MAD(oi_log_change[t-180:t-1])); exactly 180 prior four-hour intervals, no current value in denominator; zero MAD -> missing',
  'flow_shock_30d_robust':'same formula for futures_taker_imbalance',
  'interactions':'current t products as named; no other polynomial/pairwise terms'
 },
 'common_sample_policy':'S0 and S1 are evaluated on identical dates, requiring every S1 field to be finite even for S0.'
}
interactions={'frozen':True,'terms':['funding_rate_state[t]*oi_shock_30d_robust[t]','oi_shock_30d_robust[t]*flow_shock_30d_robust[t]','funding_rate_state[t]*basis_mean[t]','futures_taker_imbalance[t]*basis_mean[t]'],'other_interactions':'none'}
season={'frozen':True,'features':['5 UTC four-hour-slot dummies; slot 0 reference','6 UTC weekday dummies; Monday reference','funding schedule window = interval start hour in {00,08,16} UTC'],'usage':'included identically in both information sets; deterministic calendar only'}
registry=models()
protocol={
 'study_id':'targeted_24h_amihud_001',
 'purpose':'Test whether joint Binance USDⓈ-M perpetual derivatives history adds predictive information for 24-hour future Binance spot Amihud beyond a matched strong spot-only model; targeted classical/QML comparison.',
 'claim_scope':'Predictive information only. No causal, structural, or quantum-advantage claim.',
 'asset_frequency':{'assets':['BTC','ETH'],'frequency':'4-hour UTC','venue':'Binance spot and USDⓈ-M perpetual, same-venue limitation retained'},
 'data_policy':{'sources':['outputs/phase5_dynamic_discovery/dataset_4h.jsonl','data/processed/phase7/market_liquidity_panel_4h.csv.gz'],'no_download':True,'stage6_2023_07_to_2024_03':'Previously inspected; historical reuse is exploratory, not a new confirmatory holdout.','phase7_2024_03_to_2026_09':'Previously inspected; exploratory reuse only, not external confirmation.','development':'2021-12-01 through 2023-06-30 20:00 UTC; prior development was already used in Phase 6 and is not pristine.'},
 'primary_target':{'name':'future_amihud_24h_mean','definition':'mean(spot_amihud[t+1:t+6]); spot_amihud=1e6*abs(4-hour log return)/4-hour spot quote volume (USDT); target requires all six future intervals and ends at t+6.','assets':['BTC','ETH'],'other_targets':'excluded from primary study'},
 'target_transform':{'candidates':['T1 raw y','T2 log1p(y)','T3 log(y+1e-8)','T4 log(10000*y+1e-8)'],'epsilon':1e-8,'scale_c':10000,'selection':'select once using fixed Ridge(alpha=1), StandardScaler within each train fold and three expanding validation folds restricted to 2021-12..2022-09; score mean asset/fold MAE divided by the training-fold IQR of transformed target; lower wins; same selected transform for BTC and ETH; tie order T1,T2,T3,T4. No model-family or S0/S1 comparison is used for transformation selection. Freeze realized choice before main comparison.','rationale':'epsilon/c are fixed from the certified 1e6 Amihud units and numerical stability; no evaluation data or significance-based selection.'},
 'information_sets':{'S0':'36 lags (6 variables x t-5..t) + fixed 12 calendar indicators.','S1':'exact S0 features + 24 lags (4 derivatives x t-5..t) + 8 fixed derivative-state/change/interaction features.','comparison':'identical complete-case dates; only derivatives information differs.'},
 'preprocessing':{'linear_kernel_neural':'Compare StandardScaler and RobustScaler (median/IQR) where in the 20-config family grids; fitted independently on each inner training fold.','tree_boosting':'Raw features.','GRU':'Actual six-step sequence for base variables; static calendar/derivative features appended to GRU representation; feature scaler fit on training folds only.','imputation':'none','winsorization':'none; preserve and report tails.'},
 'innovation_features':{'oi_flow':'30-day robust shock: subtract median of exactly 180 preceding 4-hour observations and divide by 1.4826*MAD; no centered windows; zero MAD missing.','robustness':'14-day and 60-day windows are secondary only and are not used in main feature set.','changes':'one-step first differences for funding and basis.'},
 'outer_development_evaluation':{'folds':[{'id':'F1','train_start':'2021-12-01T00:00:00Z','validation_start':'2022-10-01T00:00:00Z','validation_end_exclusive':'2023-01-01T00:00:00Z'},{'id':'F2','train_start':'2021-12-01T00:00:00Z','validation_start':'2023-01-01T00:00:00Z','validation_end_exclusive':'2023-04-01T00:00:00Z'},{'id':'F3','train_start':'2021-12-01T00:00:00Z','validation_start':'2023-04-01T00:00:00Z','validation_end_exclusive':'2023-07-01T00:00:00Z'}],'inner':'For each outer fold use the 180 calendar days preceding its validation start split into three consecutive 60-day blocks; expanding train history only. Purge at least 6 four-hour intervals at each boundary; no target window crosses boundaries. Hyperparameters selected from inner folds only; outer block is scored once.','interpretation':'Nested walk-forward development OOF is internal predictive evaluation on previously used development history, not untouched confirmation.'},
 'historical_reuse_evaluation':{'fit':'Choose each family configuration using all eligible development CV through 2023-06-30; refit using development rows only.','periods':['2023-07-01 through 2024-03-03 20:00 UTC (Phase-6 period already inspected)','2024-03-04 through 2026-09-29 20:00 UTC (Phase-7 period already inspected)'],'label':'EXPLORATORY_REUSE; no claim of fresh confirmation.'},
 'families':registry,
 'search_budget':{'configs_per_family':20,'same_grid_and_trial_count_for_S0_and_S1':True,'inner_folds_per_outer':3,'primary_metric':'MAE on frozen selected target transformation','tie_rule':'registry order'},
 'primary_inference':{'paired_temporal_moving_block_bootstrap':{'replications':1000,'block_lengths_4h_intervals':[42,84],'seed':20261007,'same_resampled_dates_for_S0_S1':True},'dm_loss_difference':'HAC Bartlett Newey-West with 6 lags, secondary supporting evidence only.'},
 'multiplicity':{'direct_model_families':'Holm within each asset across 9 frozen model families.','best_model':'separate per-asset comparison.','qml':'Holm within each asset across frozen quantum configurations/families versus matched classical.','exploratory_outputs':'reported transparently; no result may upgrade an independent confirmatory claim.'},
 'residual_learning':{'target':'Observed 24h future Amihud minus strict forward OOF prediction from the development-selected strongest SPOT_ONLY model.','training_rule':'All training residuals must be generated strictly out of fold with the spot-only model fit only to earlier dates; residual derivative learners use derivatives-only information and chronological nested folds.','interpretation':'one method only -> MODEL_SENSITIVE_RESIDUAL_SIGNAL; at least two independent validated model families with paired block-bootstrap support -> RESIDUAL_INCREMENTAL_INFORMATION.'},
 'qml':{'packages':'PennyLane CPU simulator, installed/version recorded before use.','kernel':'fidelity quantum kernel with fixed angle encoding and one fixed entangling layer; 4, 6, 8 qubits; training-only PCA and scaling; deterministic 128-landmark Nyström approximation. Matched RBF kernel on identical PCA scores, dates, and landmark count.','qnn':'shallow two-layer variational circuit; angle encoding; 4/6/8 qubits; 5 seeds; Adam; training-only PCA/scaling. Matched compact MLP on identical compressed dimensions and splits.','hybrid':'single linear classical encoder to 4/6/8 latent angles, shallow quantum layer, scalar classical output; 5 seeds; constrained encoder; matched compact classical model.','encoding':'angle encoding primary only; no encoding search.','claims':'no hardware run or quantum-advantage claim.'},
 'qml_fixtures':{'linear':'y=x0+noise','nonlinear':'y=x0*x1+noise','null':'independent Gaussian noise','checks':'finite loss, non-degenerate prediction, fixed-seed reproducibility, performance above mean baseline on linear and nonlinear fixture; otherwise method validation fails and empirical method is not used.'},
 'negative_controls':{'post_target':'future derivative history t+7..t+12 predicting target t+1..t+6; compare matched SpotOnly and SpotPlusFutureDerivatives models.','random_features':'not primary; omitted.'},
 'regimes':{'threshold_source':'development only','regimes':['high/low spot RV at development median','high/normal absolute OI shock at development 90th percentile','extreme/normal absolute funding at development 90th percentile','positive/negative basis at zero','high/low Amihud at development median'],'role':'exploratory, no primary model selection.'},
 'component_ablation':{'models':'all nine families using hyperparameters selected on full development CV; no component-specific tuning.','sets':['all derivatives','Funding only','OI only','Futures Flow only','Basis only','drop Funding','drop OI','drop Futures Flow','drop Basis'],'role':'secondary; cannot replace primary matched information-set comparison.'},
 'classification_rules':{'robust_incremental':'median direct family Delta>0; >=3 independent families improve; >=2 have Holm-corrected paired-block support; >=1 supporting non-neural family; residual learning supported; best S1 competitive with/better than best S0 on historical reused periods; no serious negative-control contradiction.','nonlinear':'linear/regularized benefit weak but >=3 independent nonlinear families among kernel, tree/boosting, neural, QML improve consistently.','quantum':'QML beats matched classical nonlinear benchmark with seed stability and positive paired-block support; replicated quantum value requires both BTC and ETH.','sensitive':'any promising gain depends on a narrow subset of models/assets/periods.','historical_data_status':'All post-development periods have been inspected in prior phases; no classification can be called fresh external confirmation.'},
 'random_seeds':{'model_search':20261007,'bootstrap':20261007,'qml_seeds':[101,211,307,401,503]},
 'prohibitions':['No causal interpretation.','No new market data downloads.','No changes to Stage 3 or Phase 5-7.','No sample/target/feature/model changes after results.','No evaluation period described as fresh confirmation.']
}

(OUT/'study_protocol.md').write_text('''# Targeted 24-hour Amihud study protocol\n\n## Research question and claim scope\n\nThis study tests whether the joint state of BTC/ETH perpetual futures markets adds predictive information for the next 24 hours of Binance spot Amihud beyond a matched spot-only information set. It is predictive, not causal. Results from Binance 2023–2026 are historically reused because those dates were examined in Phases 6–7; they are exploratory rather than fresh confirmation. Stage 3 and Phases 5–7 remain unchanged.\n\n## Data, target, and timing\n\nUse only the certified 4-hour UTC Phase-5/Phase-7 panels, BTC and ETH, and no new downloads. The sole target is the arithmetic mean of spot Amihud over intervals t+1 through t+6. Spot Amihud is 1e6 times the absolute 4-hour spot log return divided by 4-hour Binance spot quote volume in USDT. Inputs comprise intervals t-5 through t; interval-t inputs become available only at its end. The future label begins at t+1 and requires all six intervals. S0 and S1 use identical complete-case rows. S0 contains the six frozen spot variables, six lags, and the same calendar controls as S1. S1 adds six lags of the four frozen derivatives variables, fixed backward-looking derivative innovations, and four prespecified economic interactions. No imputation or winsorization is used.\n\n## Amihud transform and feature construction\n\nRe-audit the numerator, quote-volume denominator, units, zeros, near-zero behavior, target-window timestamps, tails, and numerical scale before fitting models. Compare four target transforms: raw y; log1p(y); log(y+1e-8); and log(10000*y+1e-8). Epsilon=1e-8 and c=10000 are fixed from the certified 1e6 Amihud unit scaling and numerical stability, not selected on the evaluation period. Select one shared BTC/ETH transform using fixed Ridge(alpha=1), training-fold-only StandardScaler, and expanding validation folds within 2021-12 through 2022-09. Rank transformations by mean asset/fold MAE divided by training-fold transformed-target IQR; tie order is T1,T2,T3,T4. Freeze the selected transform before any main model-family or S0/S1 comparison.\n\nBase histories are t-5..t. OIShock and FlowShock use the current observation minus the median of exactly 180 preceding four-hour values, divided by 1.4826 times their preceding-window MAD; zero MAD yields missing. FundingChange and BasisChange are one-step differences. Only Funding×OIShock, OIShock×FlowShock, Funding×Basis, and FlowShock×Basis are added. Calendar controls are five UTC-slot indicators (slot 0 reference), six weekday indicators (Monday reference), and a fixed funding-settlement-window indicator for interval starts at 00:00, 08:00, or 16:00 UTC.\n\n## Samples and validation\n\nThe development period is 2021-12-01 through 2023-06-30 20:00 UTC. It has been used in earlier project work and is not pristine. Nested expanding walk-forward outer blocks are: 2022-10-01–2022-12-31; 2023-01-01–2023-03-31; and 2023-04-01–2023-06-30. For each outer block, tune only on three expanding inner folds formed by dividing the 180 calendar days preceding the block into consecutive 60-day validation windows. Purge at least six 4-hour intervals at fold boundaries, require all target labels to remain inside each validation block, and never randomly shuffle dates.\n\nThe 2023-07–2024-03 Stage-6 period and the 2024-03–2026-09 Phase-7 period can be scored only as EXPLORATORY_REUSE. Train final selected models on development data only. No period currently available is a fresh external confirmation.\n\n## Models and tuning\n\nNine classical families are frozen: ElasticNet; RBF-SVR; ExtraTrees; HistGradientBoosting; XGBoost; LightGBM; CatBoost; compact MLP; and a compact GRU. Each gets exactly 20 predefined configurations, shared between S0 and S1. For linear, kernel, and neural families, StandardScaler and RobustScaler are compared with parameters fitted inside each training fold. Tree/boosting models use unscaled features. The GRU receives a real six-step sequence plus current static/calendar features. Selection uses transformed-target MAE on inner folds only; outer predictions are paired.\n\n## Residual learning and QML\n\nGenerate strict forward OOF predictions from the development-selected strongest spot-only model, then construct observed-minus-predicted residuals. Train derivatives-only residual learners using chronological folds; no in-sample spot residual is permitted. Compare regularized linear, RBF, boosting, MLP, quantum kernel, QNN, and compact hybrid QNN.\n\nQML uses PennyLane CPU simulation, fixed angle encoding, shallow circuits, training-only scaling/PCA to 4/6/8 dimensions, and five frozen seeds for QNN/hybrid methods. Quantum kernels use a deterministic 128-landmark Nyström approximation and are matched to RBF models on the same compressed rows/features/landmarks. Validate each implementation on frozen linear, nonlinear-interaction, and null synthetic fixtures before empirical use. No hardware or quantum-advantage claim is made.\n\n## Inference, multiplicity, controls, and regimes\n\nPrimary loss is MAE on the frozen transformed target; report original-scale MAE, RMSE, median absolute error, and rank correlation as secondary metrics. Use paired moving-block bootstrap with 1,000 replications, block lengths 42 and 84 four-hour intervals, and seed 20261007. Use six-lag Bartlett HAC forecast-loss tests as supporting evidence. Apply Holm within each asset across the nine family-level direct comparisons; define separate prespecified residual and QML families. Report model-family results and best-model dominance separately; all best-model selection uses development data. Construct a derivative-only future-information negative control at t+7..t+12 and compare against the same SpotOnly benchmark. Regime thresholds are learned on development only and are exploratory. Component/drop-one ablations use development-selected parameters without retuning.\n\n## Decision rules\n\nUse the specified labels NO_INCREMENTAL_INFORMATION, LINEAR_INCREMENTAL_INFORMATION, NONLINEAR_INCREMENTAL_INFORMATION, RESIDUAL_INCREMENTAL_INFORMATION, JOINT_DERIVATIVES_STATE_INFORMATION, MODEL_SENSITIVE_SIGNAL, QUANTUM_INCREMENTAL_VALUE, and INCONCLUSIVE. A robust incremental finding requires a positive median family delta, improvement in at least three independent families, at least two Holm-adjusted paired-bootstrap supports, at least one non-neural supporting family, residual-learning support, competitive best-model performance on the reused historical periods, and no serious negative-control contradiction. Quantum incremental value requires stable multi-seed QML improvement over matched classical nonlinear models with paired uncertainty; replication requires both assets. Historical reuse cannot be described as independent confirmation.\n\nExact configuration grids, feature formulas, timestamps, fold boundaries, and seeds are in the machine-readable protocol and registries. No model result was used to define these rules.\n''')
dump('study_protocol.json',protocol)
dump('feature_registry.json',features)
