dump('seasonality_registry.json',season)
dump('model_registry.json',{'families':registry,'qml':protocol['qml']})
dump('search_budget.json',protocol['search_budget']|{'family_trials':{k:len(v) for k,v in registry.items()},'qml_qubits':[4,6,8],'qml_seeds':protocol['random_seeds']['qml_seeds']})
outer_folds=protocol['outer_development_evaluation']['folds']
inner_by_outer=[]
for outer in outer_folds:
 start=datetime.fromisoformat(outer['validation_start'].replace('Z','+00:00'))
 first=start-timedelta(days=180)
 inner=[]
 for j in range(3):
  vs=first+timedelta(days=60*j); ve=vs+timedelta(days=60)
  # Six 4-hour feature dates are purged immediately before and after each
  # validation window; the final training target ends exactly at validation start.
  inner.append({'id':f"{outer['id']}_I{j+1}",'train_start':'2021-12-01T00:00:00Z','train_end_exclusive':(vs-timedelta(hours=24)).isoformat().replace('+00:00','Z'),'validation_start':vs.isoformat().replace('+00:00','Z'),'validation_end_exclusive':ve.isoformat().replace('+00:00','Z'),'validation_feature_end_exclusive':(ve-timedelta(hours=24)).isoformat().replace('+00:00','Z'),'purge_intervals_before':6,'purge_intervals_after':6})
 inner_by_outer.append({'outer_fold':outer['id'],'inner_folds':inner})
dump('temporal_folds.json',{'target_transform_calibration':[
 {'id':'T1','train_start':'2021-12-01T00:00:00Z','validation_start':'2022-04-01T00:00:00Z','validation_end_exclusive':'2022-06-01T00:00:00Z'},
 {'id':'T2','train_start':'2021-12-01T00:00:00Z','validation_start':'2022-06-01T00:00:00Z','validation_end_exclusive':'2022-08-01T00:00:00Z'},
 {'id':'T3','train_start':'2021-12-01T00:00:00Z','validation_start':'2022-08-01T00:00:00Z','validation_end_exclusive':'2022-10-01T00:00:00Z'}],
 'outer':outer_folds,'inner_by_outer':inner_by_outer,'purge_intervals':6})
files=['study_protocol.md','study_protocol.json','feature_registry.json','interaction_registry.json','seasonality_registry.json','model_registry.json','search_budget.json','temporal_folds.json']
(OUT/'study_protocol.sha256').write_text('\n'.join(f'{sha(OUT/f)}  {f}' for f in files)+'\n')
print(json.dumps({'protocol_frozen':True,'hashes':{f:sha(OUT/f) for f in files},'model_families':{k:len(v) for k,v in registry.items()},'total_configs_per_info_set':sum(map(len,registry.values()))},indent=2))
